"""Collect current local four-robot files into one versioned import bundle."""

from hashlib import sha256
import json
from pathlib import Path
import shutil
from zipfile import ZipFile, ZIP_DEFLATED


workspace = Path(__file__).resolve().parents[1]
root = workspace / "outputs" / "formation-kit"
payload = root / "payload"


def copy(source: Path, target: Path):
    destination = payload / target
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)


old = workspace / "outputs" / "formation-reconfiguration"
for source in sorted((old / "prototype").glob("*")):
    if source.is_file():
        copy(source, Path("planner") / source.name)
for source in sorted((old / "snapshot").glob("*")):
    if source.is_file():
        copy(source, Path("baseline_robot1") / source.name)
for source in sorted((old / "evidence").glob("*")):
    if source.is_file():
        copy(source, Path("evidence") / source.name)
copy(old / "README.md", Path("docs") / "previous_record.md")
copy(old / "manifest.json", Path("docs") / "previous_manifest.json")
for source in sorted((workspace / "work" / "robot_data").glob("*")):
    if source.is_file() and source.name not in ("classroom.pgm", "classroom.yaml", "scan_overlay.png"):
        copy(source, Path("evidence") / "raw" / source.name)
for source in sorted((workspace / "work").glob("*.py")):
    category = "maintenance_manual" if source.name in ("repair_localization.py", "set_initial_poses.py") else "diagnostics"
    if source.name in ("build_formation_kit.py", "make_formation_manifest.py"):
        category = "packaging"
    copy(source, Path("tools") / category / source.name)

files = []
for source in sorted(payload.rglob("*")):
    if source.is_file():
        files.append({"path": source.relative_to(root).as_posix(), "sha256": sha256(source.read_bytes()).hexdigest(), "bytes": source.stat().st_size})
(root / "manifest.json").write_text(json.dumps({"version": "2026-09-18", "files": files}, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")

archive = workspace / "outputs" / "formation-kit-2026-09-18.zip"
with ZipFile(archive, "w", ZIP_DEFLATED) as bundle:
    for source in sorted(root.rglob("*")):
        if source.is_file():
            bundle.write(source, Path("formation-kit") / source.relative_to(root))
print(f"{len(files)} payload files; {archive.stat().st_size} archive bytes")

