const r=await tools.exec_command({cmd:"@'
import sys
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0,'outputs/formation-kit')
import run_autonomous_formation as f

def check(robot):
    result=[]
    try:
        c=f.connect(robot)
        try:
            for label,cmd in (
              ('wireless','cat /proc/net/wireless; nmcli -f IN-USE,SSID,CHAN,SIGNAL,RATE device wifi list --rescan no | head -n 12'),
              ('wlan_stats','ip -s link show wlan0; nmcli -f GENERAL.STATE,GENERAL.CONNECTION,GENERAL.HWADDR device show wlan0'),
              ('gateway_ping','ping -n -c 12 -W 1 192.168.1.1'),
              ('network_log','journalctl -u NetworkManager --since "30 minutes ago" --no-pager -q | grep -Ei "wlan0|disassoc|disconnect|deauth|signal|roam" | tail -n 30')
            ):
                try:result.append((label,f.run(c,cmd)[:3500]))
                except Exception as e:result.append((label,'ERROR '+str(e)))
        finally:c.close()
    except Exception as e:result.append(('connect','ERROR '+str(e)))
    return robot,result
with ThreadPoolExecutor(max_workers=4) as pool:
    for robot,items in pool.map(check,f.ROBOT_IDS):
        print('\n###',robot,flush=True)
        for label,value in items: print(label,value,flush=True)
